INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What does ''wet processing'' broadly refer to in textile manufacturing?', '["The group of processes (pretreatment, dyeing, printing, finishing) that use water/chemicals to prepare, color, and finish fabric","Only the mechanical weaving of warp and weft","Only the spinning of fiber into yarn","The dry storage and packaging of finished garments"]'::jsonb, 'The group of processes (pretreatment, dyeing, printing, finishing) that use water/chemicals to prepare, color, and finish fabric', 'Wet processing covers all water/chemical-based fabric treatments after weaving/knitting — pretreatment (desizing, scouring, bleaching), coloration (dyeing, printing), and finishing — as opposed to the ''dry'' mechanical processes of spinning and fabric formation.', 1, '{"wet-processing-overview"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''desizing'' and why is it typically the FIRST wet-processing step for woven fabric?', '["Removing the size (starch/PVA) applied to warp yarn before weaving, which must be removed before other wet processes can work effectively","Adding a protective size coating to the fabric for the first time","The final finishing step applied after dyeing","A process that only applies to knitted fabric, never woven"]'::jsonb, 'Removing the size (starch/PVA) applied to warp yarn before weaving, which must be removed before other wet processes can work effectively', 'Since sizing chemicals coat warp yarn to protect it during weaving, that same coating would block scouring/bleaching/dyeing chemicals from reaching the fiber — desizing removes it first so downstream wet processes work effectively.', 1, '{"desizing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is a common method for desizing starch-based size from cotton fabric?', '["Enzymatic treatment (amylase enzymes) that break down starch into water-soluble sugars for easy washing off","Applying more starch to strengthen the size further","Mechanical brushing alone, with no chemicals used","High-temperature dry heat with no water involved"]'::jsonb, 'Enzymatic treatment (amylase enzymes) that break down starch into water-soluble sugars for easy washing off', 'Amylase enzymes specifically break down starch molecules into smaller, water-soluble sugar units, allowing the size to be easily rinsed away — a widely used, relatively mild and effective desizing method for starch-sized fabric.', 1, '{"desizing","enzyme"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the typical wet-processing sequence for grey (unprocessed) woven cotton fabric before dyeing?', '["Desizing → Scouring → Bleaching","Bleaching → Desizing → Scouring","Dyeing → Scouring → Desizing","Scouring → Dyeing → Desizing"]'::jsonb, 'Desizing → Scouring → Bleaching', 'The standard pretreatment sequence removes size first (desizing), then removes natural impurities (scouring), then whitens the fabric (bleaching) — each step builds on the previous one''s cleaning to prepare fabric for uniform dyeing.', 1, '{"pretreatment-sequence"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What does ''pH'' control matter for during wet processing (e.g., scouring, dyeing, finishing)?', '["Many wet-processing chemicals (enzymes, dyes, finishing agents) only work effectively within specific pH ranges; incorrect pH can reduce effectiveness or damage the fabric","pH has no relevance to any wet-processing step","pH only matters for the final drying stage, not chemical treatment","pH control is only relevant to synthetic fiber, never cotton"]'::jsonb, 'Many wet-processing chemicals (enzymes, dyes, finishing agents) only work effectively within specific pH ranges; incorrect pH can reduce effectiveness or damage the fabric', 'Enzymes have narrow optimal pH ranges, dyes have specific pH requirements for exhaustion/fixation, and incorrect pH can cause fiber damage (e.g., strong alkali on wool) or poor results — pH control is a critical parameter throughout wet processing.', 1, '{"ph-control"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''padding'' (pad application) as a method of applying chemicals/dyes to fabric?', '["Passing fabric through a chemical/dye bath, then through squeeze rollers (nip) to apply a controlled, uniform wet pickup","A process that only removes chemicals from fabric, never applies them","A purely mechanical process with no liquid involved","A method used only for dry powder application"]'::jsonb, 'Passing fabric through a chemical/dye bath, then through squeeze rollers (nip) to apply a controlled, uniform wet pickup', 'Pad application saturates fabric in a trough of liquor, then passes it through nip rollers that squeeze out excess liquid, leaving a controlled, uniform percentage of liquor (wet pickup %) on the fabric — used for continuous dyeing and many finishing treatments.', 1, '{"pad-application"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What does ''wet pickup %'' refer to in pad application processes?', '["The percentage of liquor (by weight) retained on the fabric after passing through the padding nip rollers, relative to the fabric''s dry weight","The percentage of dye that exhausts from the bath onto the fiber","The total water used to prepare the dye bath","The percentage of fabric shrinkage after padding"]'::jsonb, 'The percentage of liquor (by weight) retained on the fabric after passing through the padding nip rollers, relative to the fabric''s dry weight', 'Wet pickup % = (weight of liquor retained / dry fabric weight) × 100 — a critical control parameter since it directly determines how much dye/chemical actually gets applied to the fabric during pad processes, requiring precise recipe calculation.', 2, '{"wet-pickup"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'In a pad-batch dyeing process, why is fabric typically ''batched'' (rolled up and stored, often rotating slowly) for a period after padding, rather than immediately going to a wash step?', '["The batching period allows sufficient time for the dye to react/fix with the fiber at ambient or controlled temperature, without needing a separate heating/steaming stage","Batching serves no functional purpose and is purely a historical tradition","Batching is done only to dry the fabric completely before any dye is applied","Batching removes all dye that was just applied, requiring re-dyeing"]'::jsonb, 'The batching period allows sufficient time for the dye to react/fix with the fiber at ambient or controlled temperature, without needing a separate heating/steaming stage', 'Pad-batch dyeing relies on a slow, extended dwell/batching time (often many hours) for the applied dye and alkali to react and fix onto the fiber at room or mildly controlled temperature — an energy-efficient alternative to continuous pad-steam methods that use high-temperature steaming for fast fixation.', 2, '{"pad-batch-dyeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is the main functional difference between ''pad-batch'' and ''pad-steam'' dyeing methods?', '["Pad-batch relies on a long dwell time at low/ambient temperature for fixation; pad-steam uses a short high-temperature steaming stage for rapid fixation","Pad-steam uses no dye at all, only physical steam pressure","Pad-batch requires no chemicals whatsoever, only water","There is no real difference; the two terms describe the identical process"]'::jsonb, 'Pad-batch relies on a long dwell time at low/ambient temperature for fixation; pad-steam uses a short high-temperature steaming stage for rapid fixation', 'Pad-batch trades time for energy savings (long ambient dwell, no steam needed), while pad-steam trades energy/steam infrastructure for speed (short, high-temperature steaming quickly fixes the dye) — both are continuous dye-application methods with different fixation mechanisms.', 2, '{"pad-batch","pad-steam"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the purpose of an Effluent Treatment Plant (ETP) at a textile wet-processing facility?', '["To treat wastewater (containing dye, chemicals, and other pollutants) before it is discharged, reducing environmental impact","To dye fabric using recycled wastewater with no treatment at all","To store finished dyed fabric before shipping","To generate electricity for the dyeing machines only"]'::jsonb, 'To treat wastewater (containing dye, chemicals, and other pollutants) before it is discharged, reducing environmental impact', 'Textile wet processing generates wastewater loaded with dye residues, salts, and processing chemicals; an ETP treats this effluent (via physical, chemical, and/or biological methods) to reduce pollutant levels before discharge, meeting environmental regulations.', 1, '{"etp","effluent-treatment"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is high dye exhaustion (efficient dye uptake onto fabric) considered environmentally beneficial, beyond just cost savings?', '["Higher exhaustion means less unused dye remains in the wastewater, reducing the pollutant/color load that the ETP must treat","Exhaustion percentage has no relationship to wastewater quality at all","Higher exhaustion always means more chemical usage overall, which is worse environmentally","Dye exhaustion only affects fabric shade, never the environment"]'::jsonb, 'Higher exhaustion means less unused dye remains in the wastewater, reducing the pollutant/color load that the ETP must treat', 'Since exhaustion measures how much dye transfers from the bath to the fabric, higher exhaustion directly means less residual dye left in the spent dye liquor/wastewater — reducing color and chemical load on the ETP and lowering overall environmental impact.', 2, '{"dye-exhaustion","environment"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is ''COD'' (Chemical Oxygen Demand) used to measure in textile wastewater testing?', '["The amount of oxygen required to chemically oxidize organic and inorganic pollutants in the water — an indicator of overall pollution load","The exact color/shade of the dye used","The temperature of the wastewater at discharge","The total volume of water used in one dyeing batch"]'::jsonb, 'The amount of oxygen required to chemically oxidize organic and inorganic pollutants in the water — an indicator of overall pollution load', 'COD quantifies the oxygen needed to chemically break down pollutants in wastewater; textile effluent (with dyes, sizing agents, surfactants) often has significant COD, making it a key parameter tracked and regulated for ETP performance and discharge compliance.', 1, '{"cod","wastewater-testing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is ''azo dye'' restriction primarily concerned with in textile regulations (e.g., REACH, Oeko-Tex)?', '["Certain azo dyes can break down under reductive conditions to release banned carcinogenic aromatic amines, so their use is restricted/tested for","Azo dyes are restricted because they are always more expensive than other dye classes","Azo dyes cannot be used on any textile fiber under any circumstances","The restriction relates only to dye color depth, not chemical safety"]'::jsonb, 'Certain azo dyes can break down under reductive conditions to release banned carcinogenic aromatic amines, so their use is restricted/tested for', 'A subset of azo dyes can be reductively cleaved (e.g., under skin contact/perspiration conditions) to release specific aromatic amines identified as carcinogenic; regulations like REACH restrict these specific azo dyes and require testing for the banned amines in finished textiles, not azo dyes as a whole class.', 2, '{"azo-dye-restriction"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is ''formaldehyde content'' testing concerned with in finished textile products?', '["Residual free formaldehyde from certain finishing treatments (like durable-press resins), which can cause skin irritation/allergic reactions above certain limits","The total dye concentration used on the fabric","The exact fiber content percentage in a blended fabric","The water usage during the dyeing process"]'::jsonb, 'Residual free formaldehyde from certain finishing treatments (like durable-press resins), which can cause skin irritation/allergic reactions above certain limits', 'Formaldehyde-based cross-linking agents (used in durable-press/wrinkle-resistant finishes) can leave residual free formaldehyde in the fabric; because formaldehyde can cause skin sensitization/irritation, standards like Oeko-Tex set strict limits on residual content, especially for garments in direct skin contact.', 2, '{"formaldehyde-testing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What does ''water hardness'' (calcium/magnesium content) potentially affect during dyeing?', '["Hard water can interfere with dye solubility/reactivity and interact with certain dyes/chemicals, causing uneven shade or reduced fastness","Water hardness has zero effect on any dyeing outcome","Hard water always improves dye fixation regardless of dye class","Water hardness only matters for the final drying step, not dyeing itself"]'::jsonb, 'Hard water can interfere with dye solubility/reactivity and interact with certain dyes/chemicals, causing uneven shade or reduced fastness', 'Calcium and magnesium ions in hard water can react with certain dyes and auxiliary chemicals (forming insoluble precipitates or altering reaction kinetics), potentially causing shade variation, unevenness, or reduced overall dyeing quality — water softening/conditioning is often needed for consistent results.', 2, '{"water-hardness"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is the purpose of a ''sequestering agent'' (chelating agent) added during dyeing?', '["To bind/deactivate metal ions (like calcium, magnesium, iron) in the water or fabric that could otherwise interfere with dye performance","To add extra color depth to the dye bath","To increase the water''s hardness intentionally","To remove all dye from the fabric after processing"]'::jsonb, 'To bind/deactivate metal ions (like calcium, magnesium, iron) in the water or fabric that could otherwise interfere with dye performance', 'Sequestering (chelating) agents bind free metal ions in solution, preventing them from reacting with dyes/chemicals or causing catalytic damage (e.g., iron-catalyzed peroxide decomposition in bleaching) — helping ensure consistent, predictable wet-processing results.', 2, '{"sequestering-agent"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'Why is ''levelness'' (uniform, even shade across the entire fabric) a key quality goal in dyeing, and what commonly causes UNEVEN dyeing (unlevelness)?', '["Uneven dye exhaustion rate across different fabric areas — often from temperature/liquor flow variation or fiber inconsistency — causes visible shade variation (unlevelness)","Unlevel dyeing is always caused by using too little dye overall, never by process variation","Levelness is unrelated to temperature or liquor circulation in the dyeing machine","Unlevel dyeing can only happen with disperse dyes, never with reactive dyes"]'::jsonb, 'Uneven dye exhaustion rate across different fabric areas — often from temperature/liquor flow variation or fiber inconsistency — causes visible shade variation (unlevelness)', 'If different parts of the fabric experience different temperature, liquor flow rate, or fiber absorbency during dyeing, they exhaust dye at different rates, creating visible shade variation (unlevel dyeing) — good machine design, leveling agents, and controlled heating/circulation profiles help prevent this.', 2, '{"levelness","unlevel-dyeing"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a ''leveling agent'' used for in dyeing?', '["To control/slow the rate of dye uptake, allowing more even, uniform dye distribution across the fabric before final fixation","To permanently fix dye onto the fabric immediately upon contact","To remove all impurities from raw fiber before dyeing","To increase fabric width during the dyeing process"]'::jsonb, 'To control/slow the rate of dye uptake, allowing more even, uniform dye distribution across the fabric before final fixation', 'Leveling agents work by temporarily competing with the fiber for dye molecules or by moderating exhaustion rate, slowing down dye uptake so it has time to migrate/distribute evenly across the fabric rather than exhausting unevenly and quickly in some areas.', 2, '{"leveling-agent"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'basic', 'multiple_choice', 'What is the general purpose of a ''softener'' finish applied to fabric?', '["To improve fabric hand-feel (softness) and reduce friction/stiffness, often by coating fibers with lubricating chemicals","To permanently increase fabric wrinkle formation","To remove all dye color from the fabric","To add stiffness and rigidity to the fabric"]'::jsonb, 'To improve fabric hand-feel (softness) and reduce friction/stiffness, often by coating fibers with lubricating chemicals', 'Softener finishes (often silicone-based or cationic surfactants) coat individual fibers with a thin lubricating layer, reducing inter-fiber friction and giving the fabric a smoother, softer hand-feel and improved drape.', 1, '{"softener-finish"}'::text[]),
('33333333-3333-3333-3333-333333333333', 'intermediate', 'multiple_choice', 'What is a ''water-repellent'' (DWR) finish designed to do, and how does it typically work?', '["It coats fiber surfaces with a low-surface-energy substance (like fluorocarbon or silicone) that causes water to bead up and roll off rather than wetting/absorbing into the fabric","It chemically bonds with water molecules, permanently absorbing them into the fiber","It makes the fabric completely impermeable to both water and air","It works only by increasing fabric thickness, without any chemical treatment"]'::jsonb, 'It coats fiber surfaces with a low-surface-energy substance (like fluorocarbon or silicone) that causes water to bead up and roll off rather than wetting/absorbing into the fabric', 'DWR (durable water repellent) finishes lower the fabric surface energy so water forms beads (high contact angle) instead of spreading/wetting the surface — the fabric can still ''breathe'' (permit air/vapor) since it''s not a solid waterproof coating, just a surface treatment that resists surface wetting.', 2, '{"water-repellent-finish"}'::text[]);
